/** Question chips — generated by the agent per listing + conversation (see Panel). */
export default function Starters({ busy, questions, loading, onPick }) {
  return (
    <div className={`starters${loading ? ' loading' : ''}`} hidden={busy}>
      {questions.map((s) => (
        <button key={s} type="button" onClick={() => onPick(s)}>
          {s}
        </button>
      ))}
    </div>
  );
}
